  if(values.contains(key)){auto v=values[key];if(v.is_string()){std::string all=specs[id].choices,want=v;int index=0;size_t pos=0;bool found=false;while(pos<=all.size()){auto end=all.find('|',pos);if(all.substr(pos,end-pos)==want){value=index;found=true;break;}if(end==std::string::npos)break;pos=end+1;index++;}if(!found)return;}else value=v.get<double>();}
